package com.vandorlabs.neoforge.door;

import com.google.gson.*;
import com.vandorlabs.neoforge.fluid.NativeFluidSlots;
import java.nio.file.*;
import net.minecraft.core.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.*;

/** Actual per-part inherited source decisions, followed by saved ownership and real removal. */
final class LargeDoorGushChecks {
    static Block replaceable;
    static final class Replaceable extends Block {Replaceable(){super(net.minecraft.world.level.block.state.BlockBehaviour.Properties.of().replaceable().noCollission());}}
    private static final BlockPos SAVED=new BlockPos(104,90,104);
    private static final int[][] FLUIDS={{0,0},{1,0},{0,1},{1,1},{1,2},{1,3}};
    private static void need(boolean value,String message){if(!value)throw new AssertionError("Large gush "+message);}
    private static NativeLargeDoorEntity host(ServerLevel level,BlockPos pos){return (NativeLargeDoorEntity)level.getBlockEntity(pos);}
    private static BlockPos anchor(Direction face){return SAVED.east(face.get2DDataValue()*32);}
    private static CompoundTag fluid(int first,int second,int amount){var raw=new CompoundTag();var slots=new CompoundTag();for(int side=0;side<2;side++){int kind=side==0?first:second;if(kind==0)continue;var tag=new CompoundTag();tag.putString("FluidName",kind==1?"water":kind==2?"lava":"fixture:unknown");tag.putInt("Amount",amount);if(kind==3)tag.putString("Owner","opaque:outlet");slots.put("Side"+side,tag);}raw.put(NativeFluidSlots.KEY,slots);return raw;}
    static void write(ServerLevel level,NativeLargeDoorBlock block)throws Exception{
        for(Direction face:Direction.Plane.HORIZONTAL){var anchor=anchor(face);for(int x=-5;x<=5;x++)for(int z=-5;z<=5;z++){var at=anchor.offset(x,0,z);level.getChunkAt(at);level.setBlock(at.below(),Blocks.STONE.defaultBlockState(),Block.UPDATE_KNOWN_SHAPE);for(int y=0;y<5;y++)level.setBlock(at.above(y),Blocks.AIR.defaultBlockState(),Block.UPDATE_KNOWN_SHAPE);}for(int x=0;x<3;x++)for(int y=0;y<3;y++){var at=anchor.relative(face.getCounterClockWise(),x).above(y);level.setBlock(at,block.defaultBlockState().setValue(NativeLargeDoorBlock.FACING,face),Block.UPDATE_KNOWN_SHAPE);host(level,at).assign(anchor);}}
        int cases=0;try(var lines=Files.lines(Path.of(System.getProperty("vandorlabs.largeDoorGushReference")))){for(String line:(Iterable<String>)lines::iterator){var row=JsonParser.parseString(line).getAsJsonObject();var face=Direction.from3DDataValue(row.get("face").getAsInt());var anchor=anchor(face);boolean open=row.get("open").getAsBoolean();for(int x=0;x<3;x++)for(int y=0;y<4;y++){var cell=anchor.relative(face.getCounterClockWise(),x).above(y);level.setBlock(cell.relative(face),Blocks.AIR.defaultBlockState(),Block.UPDATE_CLIENTS);level.setBlock(cell.relative(face.getOpposite()),Blocks.AIR.defaultBlockState(),Block.UPDATE_CLIENTS);}for(int x=0;x<3;x++)for(int y=0;y<3;y++){var at=anchor.relative(face.getCounterClockWise(),x).above(y);level.setBlock(at,block.defaultBlockState().setValue(NativeLargeDoorBlock.FACING,face).setValue(NativeLargeDoorBlock.OPEN,open),Block.UPDATE_CLIENTS);host(level,at).containedFluids().read(new CompoundTag(),level.registryAccess());}
            int role=row.get("role").getAsInt(),half=row.get("half").getAsInt(),profile=row.get("profile").getAsInt(),target=row.get("target").getAsInt();var pos=anchor.relative(face.getCounterClockWise(),role/3).above(role%3);var owner=host(level,pos);owner.setWaterOutlets(row.get("previous").getAsBoolean()?255:0);if(role%3+half<3)host(level,pos.above(half)).containedFluids().read(fluid(FLUIDS[profile][0],FLUIDS[profile][1],1000),level.registryAccess());var state=target==0?Blocks.AIR.defaultBlockState():target==1?Blocks.WATER.defaultBlockState():target==2?Blocks.WATER.defaultBlockState().setValue(LiquidBlock.LEVEL,3):target==3?Blocks.LAVA.defaultBlockState():target==4?Blocks.STONE.defaultBlockState():replaceable.defaultBlockState();for(int h=0;h<2;h++){level.setBlock(pos.above(h).relative(face),state,Block.UPDATE_CLIENTS);level.setBlock(pos.above(h).relative(face.getOpposite()),state,Block.UPDATE_CLIENTS);}
            NativeDoorWaterGush.update(owner,row.get("stop").getAsBoolean());need(owner.waterOutlets()==row.get("mask").getAsInt(),"source mask "+row+" actual="+owner.waterOutlets());var expected=row.getAsJsonArray("states");for(int h=0;h<2;h++)for(int d=0;d<4;d++){var actual=level.getBlockState(pos.above(h).relative(Direction.from2DDataValue(d)));int value=actual.getBlock() instanceof LiquidBlock&&actual.getFluidState().is(net.minecraft.tags.FluidTags.WATER)?actual.getValue(LiquidBlock.LEVEL):actual.getBlock() instanceof NativeLargeDoorBlock?-6:actual.isAir()?-1:actual.getFluidState().is(net.minecraft.tags.FluidTags.LAVA)?-3:actual.is(Blocks.STONE)?-4:-5;need(value==expected.get(h*4+d).getAsInt(),"source outlet "+row+" index="+(h*4+d)+" actual="+value);}cases++;
        }}need(cases==20736,"complete actual source matrix");
        var face=Direction.SOUTH;var anchor=anchor(face);for(int x=0;x<3;x++)for(int y=0;y<3;y++){var at=anchor.relative(face.getCounterClockWise(),x).above(y);level.setBlock(at,block.defaultBlockState().setValue(NativeLargeDoorBlock.FACING,face).setValue(NativeLargeDoorBlock.OPEN,true),Block.UPDATE_CLIENTS);host(level,at).containedFluids().read(new CompoundTag(),level.registryAccess());host(level,at).setWaterOutlets(0);for(var out:new BlockPos[]{at.relative(face),at.relative(face.getOpposite())})level.setBlock(out,Blocks.AIR.defaultBlockState(),Block.UPDATE_CLIENTS);}
        var part=host(level,anchor.east(2).above());part.containedFluids().read(fluid(1,3,777),level.registryAccess());part.containedFluidsChanged();part.tickWaterGush();need(part.waterOutlets()==1&&level.getFluidState(part.getBlockPos().south()).isSource(),"local nonanchor ticker publishes owned source");need(host(level,anchor).waterOutlets()==0&&!part.itemSettings().contains("DoorWaterOutlets"),"outlet masks stay private and per-part");System.out.println("[vandorlabs][large-door-gush] write PASS cases="+cases+" all9rawroles/two-row masks/known+opaque/nonanchor ticker/saved source");
    }
    static void read(ServerLevel level){var anchor=anchor(Direction.SOUTH);level.getChunkAt(anchor);var root=host(level,anchor);var part=host(level,anchor.east(2).above());need(root!=null&&part!=null&&root.waterOutlets()==0&&part.waterOutlets()==1&&part.containedFluids().get(0).getAmount()==777&&part.containedFluids().raw(1).getString("Owner").equals("opaque:outlet"),"saved per-part source and opaque slots");var out=part.getBlockPos().south();NativeLargeDoorLifecycle.setState(level,root,false,false);part.containedFluidsChanged();part.tickWaterGush();need(part.waterOutlets()==0&&level.getBlockState(out).getValue(LiquidBlock.LEVEL)==1,"closed nonanchor tick retires owned source");NativeLargeDoorLifecycle.setState(level,root,false,true);part.containedFluidsChanged();part.tickWaterGush();need(part.waterOutlets()==1&&level.getFluidState(out).isSource(),"fluid-change scheduling resumes source");level.removeBlock(part.getBlockPos(),false);need(level.getBlockState(out).getValue(LiquidBlock.LEVEL)==1,"actual follower removal drains its source before tile removal");System.out.println("[vandorlabs][large-door-gush] read PASS per-part restart/close/resume/actual removal");}
}
